// scripts/gen-android-assets.mjs
//
// Generates the Android launcher icons + splashes for the Greek Stack Capacitor
// app from the CANONICAL navy seal VECTOR (brand/greekstack-seal.svg) — NOT a
// raster. android/ is gitignored and regenerated by `cap add android`; the
// tracked source of truth is this script + brand/greekstack-seal.svg.
//   node scripts/gen-android-assets.mjs
//
// Replaces the prior cream navy-temple raster (public/brand/greekstack-mark-alt
// .png) the owner flagged as "AI slop": the seal is the elevated classical
// temple (capitals + bases + gold accents + stepped stylobate), rendered crisp
// from vector at every density.

import sharp from "sharp";
import path from "node:path";
import { fileURLToPath } from "node:url";
import fs from "node:fs";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");

// The canonical navy seal vector (full navy tile + ivory temple + gold accents).
const SEAL = path.join(root, "brand", "greekstack-seal.svg");
const RES = path.join(root, "android/app/src/main/res");

const NAVY = { r: 11, g: 27, b: 58, alpha: 1 }; // #0B1B3A — the seal tile navy

// Rasterize the seal vector at a target box, transparent background, so it can
// be composited / flattened per surface.
function sealAt(px, opts = {}) {
  const density = Math.max(96, Math.round((px / 100) * 96) + 96);
  return sharp(fs.readFileSync(SEAL), { density })
    .resize(px, px, { fit: "contain", background: { r: 0, g: 0, b: 0, alpha: 0 }, ...opts });
}

const LAUNCHER_SIZES = [
  { density: "mdpi", icon: 48, foreground: 108 },
  { density: "hdpi", icon: 72, foreground: 162 },
  { density: "xhdpi", icon: 96, foreground: 216 },
  { density: "xxhdpi", icon: 144, foreground: 324 },
  { density: "xxxhdpi", icon: 192, foreground: 432 },
];

const SPLASHES = [
  { folder: "drawable", w: 512, h: 512, markScale: 0.5 },
  { folder: "drawable-land-mdpi", w: 480, h: 320, markScale: 0.25 },
  { folder: "drawable-land-hdpi", w: 800, h: 480, markScale: 0.25 },
  { folder: "drawable-land-xhdpi", w: 1280, h: 720, markScale: 0.25 },
  { folder: "drawable-land-xxhdpi", w: 1600, h: 960, markScale: 0.25 },
  { folder: "drawable-land-xxxhdpi", w: 1920, h: 1280, markScale: 0.25 },
  { folder: "drawable-port-mdpi", w: 320, h: 480, markScale: 0.25 },
  { folder: "drawable-port-hdpi", w: 480, h: 800, markScale: 0.25 },
  { folder: "drawable-port-xhdpi", w: 720, h: 1280, markScale: 0.25 },
  { folder: "drawable-port-xxhdpi", w: 960, h: 1600, markScale: 0.25 },
  { folder: "drawable-port-xxxhdpi", w: 1280, h: 1920, markScale: 0.25 },
];

async function generateLauncherIcons() {
  for (const item of LAUNCHER_SIZES) {
    const mipmapDir = path.join(RES, `mipmap-${item.density}`);
    if (!fs.existsSync(mipmapDir)) {
      fs.mkdirSync(mipmapDir, { recursive: true });
    }

    // 1. Regular icon — the full navy seal flattened (square; OS masks corners).
    const iconBuf = await sealAt(item.icon)
      .flatten({ background: NAVY })
      .removeAlpha()
      .png()
      .toBuffer();
    await sharp(iconBuf).toFile(path.join(mipmapDir, "ic_launcher.png"));

    // 2. Round icon — same seal (the launcher applies the circular mask).
    const roundBuf = await sealAt(item.icon)
      .flatten({ background: NAVY })
      .removeAlpha()
      .png()
      .toBuffer();
    await sharp(roundBuf).toFile(path.join(mipmapDir, "ic_launcher_round.png"));

    // 3. Foreground icon — the seal centered in the adaptive-icon safe zone, on
    //    a transparent field (the launcher composites it over the gold/navy bg).
    const fgMarkSize = Math.round(item.foreground * 0.7);
    const fgMark = await sealAt(fgMarkSize)
      .png()
      .toBuffer();
    const fgOffset = Math.round((item.foreground - fgMarkSize) / 2);

    const fgBuf = await sharp({
      create: { width: item.foreground, height: item.foreground, channels: 4, background: { r: 0, g: 0, b: 0, alpha: 0 } },
    })
      .composite([{ input: fgMark, top: fgOffset, left: fgOffset }])
      .png()
      .toBuffer();
    await sharp(fgBuf).toFile(path.join(mipmapDir, "ic_launcher_foreground.png"));
    
    console.log(`✓ Mipmap-${item.density} launcher icons`);
  }
}

async function generateSplashes() {
  for (const item of SPLASHES) {
    const drawDir = path.join(RES, item.folder);
    if (!fs.existsSync(drawDir)) {
      fs.mkdirSync(drawDir, { recursive: true });
    }

    const minDim = Math.min(item.w, item.h);
    const markSize = Math.round(minDim * item.markScale);

    const mark = await sealAt(markSize)
      .png()
      .toBuffer();

    const topOffset = Math.round((item.h - markSize) / 2);
    const leftOffset = Math.round((item.w - markSize) / 2);

    const splashBuf = await sharp({
      create: { width: item.w, height: item.h, channels: 4, background: NAVY },
    })
      .composite([{ input: mark, top: topOffset, left: leftOffset }])
      .flatten({ background: NAVY })
      .removeAlpha()
      .png()
      .toBuffer();

    await sharp(splashBuf).toFile(path.join(drawDir, "splash.png"));
    console.log(`✓ Splash in ${item.folder} (${item.w}x${item.h})`);
  }
}

await generateLauncherIcons();
await generateSplashes();
console.log("Done generating Android assets.");
